import heapq

def solution(edges, N):
    # Extend the list with a sentinel node
    edges.extend([(-1, -1)] * N)
    start = 0  # Start at the first node
    graph = [[] for _ in range(N + 1)]
    result = [0]

    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    def dijkstra(start):
        distances = [float('inf')] * (N + 1)
        distances[start] = 0
        pq = [(0, start)]
        while pq:
            dist, node = heapq.heappop(pq)
            if dist > distances[node]:
                continue
            for neighbor in graph[node]:
                if neighbor == start:
                    continue
                new_dist = distances[node] + 1
                if new_dist < distances[neighbor]:
                    distances[neighbor] = new_dist
                    heapq.heappush(pq, (new_dist, neighbor))
        result.append(max(result[-1] + distances[i] for i in range(N + 1) if distances[i] > 0))

    dijkstra(start)
    return result[1]

# Example usage
N = 10
edges = [(0, 1), (0, 3), (0, 4), (0, 9), (1, 2), (2, 3), (2, 7), (4, 5), (4, 6), (7, 8)]
print(solution(edges, N))  # Output: 51
