    count, range_start, range_end = 0, 1, 2
    while root >= range_start + range_end:
        if n % root == 0:
            if (root - 1) / 2 in [range_start, range_start + range_end]:
                count += 1
            if range_end > root:
                root -= 1
            else:
                root += 1
                range_end = root
        else:
            root -= 1
    if n > 2:
        return 0
    return count

def main():
    n = int(input().strip())
    print(find_ways(n))

if __name__ == "__main__":
    main()
