import sys
from typing import List

def dfs(num_list: List[int], visited: List[bool], k: int) -> int:
    if k == len(num_list):
        return 0
    max_steps = 0
    for i in range(k + 1):
        if not visited[i] and num_list[i] % (-num_list[0] // math.gcd(num_list[i], num_list[0])) == 0:
            visited[i] = True
            steps = dfs(num_list, visited, k - i)
            max_steps = max(max_steps, steps)
            visited[i] = False
    return max_steps + 1

def find_max_steps(to_delete: List[int]) -> int:
    N = len(to_delete)
    C = 50
    max_steps = 0
    for C in range(1, 51):
        unique = set(to_delete)
        freqs = [0] * (N + 1)
        for num in to_delete:
            freqs[int(num)] += 1
        for i in range(1, N + 1):
            freqs[i] += freqs[i - 1]
        max_val = max(freqs[i] for i in range(N + 1))
        if max_val - 1 >= N:
            break
        unique = sorted(unique)
        S = 0
        for i in range(N):
            if freqs[i + 1] < max_val:
                S += freqs[i] // 2
        while S < max_val - 1:
            S += C
        num_list = [0] * N
        for i in range(N):
            for ii in range(freqs[i] // 2):
                num_list[i + ii] = unique[i]
            if i > 0 and num_list[i] < num_list[i - 1] * C:
                num_list[i] = num_list[i - 1] * C
                max_val = max(num_list[i], max_val)
        unique = num_list[:N]
        max_steps = max(max_steps, dfs(unique, [False] * len(unique), N))
    return max_steps

T = int(sys.stdin.readline().strip())
for _ in range(T):
    N, K, C = map(int, sys.stdin.readline().strip().split())
    nums = list(map(int, sys.stdin.readline().strip().split()))
    print(find_max_steps(nums))
