M, N = map(int, input().split())
mod = 998244353

memo = {}

def count_colorings(row, col, blue_ind):
    if (row, col, blue_ind) in memo:
        return memo[(row, col, blue_ind)]
    if row == M or col == N:
        if row == M:
            blue_needed = blue_ind == 0
        else:
            yellow_needed = blue_ind == 1
        if blue_needed and yellow_needed:
            return 1
        else:
            return 0
    if blue_ind == 0:
        yellow = absorb(row, N - 1)
    else:
        yellow = absorb(0, col)

    total = 0
    for start in range(N):
        if not yellow[start] and (col - start - 1 == yellow[row + 1] or (row == M and start < N - 1)):
            total = (total + count_colorings(row + 1, start + 1, "{:b}".format(blue_ind).zfill(4)[row % 4])) % mod
    memo[(row, col, blue_ind)] = total
    return total

def absorb(start, end):
    yellow = []
    for i in range(start, end + 1):
        yellow.append(1)
    return yellow

